import numpy as np
from scipy.spatial.transform import Rotation as Rot
q=np.array([0,-1.04758,0,-2.63996,0,1.53564,-2.32]); aa=np.array([0,0,0,.0825,-.0825,0,.088]);dd=[.333,0,.316,0,.384,0,0];al=[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]
def tx(x):
 t=np.eye(4);t[0,3]=x;return t
def tz(x):
 t=np.eye(4);t[2,3]=x;return t
def rx(x):
 t=np.eye(4);t[:3,:3]=Rot.from_euler('x',x).as_matrix();return t
def rz(x):
 t=np.eye(4);t[:3,:3]=Rot.from_euler('z',x).as_matrix();return t
T=np.eye(4)
for a,d,alpha,theta in zip(aa,dd,al,q):T=T@rx(alpha)@tx(a)@rz(theta)@tz(d)
for name,t in [('flange',np.eye(4)),('tcp',tz(.107)),('tcp_rot',tz(.107)@rz(-np.pi/4))]:
 p=(T@t);p[:3,3]+=np.array([0,-.4,.78]);print(name,p[:3,3],Rot.from_matrix(p[:3,:3]).as_quat(),p[:3,:3])
